const PERSON_PARAMS: Readonly<Record<string, string>> = {
  lordId: "lord", guardianId: "guardian", candidateId: "candidate", heirId: "heir", mayorId: "mayor", leaderId: "leader", predecessorId: "predecessor",
  // LM-E4: the steward of an estate (an estate person).
  stewardId: "steward",
  // FIX-13 (ES-11): a person off the map who died (a neighbour house's, a steward).
  deceasedId: "deceased",
};
export type PersonReader = Partial<Pick<GameState, "persons" | "factions" | "estates">>;

/** The town's people (living and past), the factions' and the neighbour estates' — by id (rebuilt when one of them changes). */
function personNamed(state: PersonReader, id: string): Person | undefined {
  const key = state.persons ?? state;
  const factions = state.factions?.people, estates = state.estates?.people;
  let entry = personIndex.get(key);
  if (entry === undefined || entry.factions !== factions || entry.estates !== estates) {
    entry = { factions, estates, byId: new Map([...(estates ?? []), ...(factions ?? []), ...(state.persons?.past ?? []), ...(state.persons?.people ?? [])]
      .map(person => [person.id, person])) };
    personIndex.set(key, entry);
  }
  return entry.byId.get(id);
}

/**

export function historyParams(record: Pick<HistoryRecord, "params">, state?: PersonReader): HistoryParams {
  const params = record.params ?? {};
  if (!namesPerson(record)) return params;
  const named: Record<string, string | number> = { ...params };
  for (const [idKey, nameKey] of Object.entries(PERSON_PARAMS)) {
    const id = params[idKey];
    if (typeof id !== "string") continue;
    const person = state === undefined || id === "" ? undefined : personNamed(state, id);
    named[nameKey] = person !== undefined ? personDisplayName(person) : typeof params[nameKey] === "string" ? params[nameKey] : PERSON_NAME_FALLBACK[nameKey] ?? "";
  }
  return named;
}

/** FIX-11: find the guardian for a minor lord (mother → adult blood kin → null = overlord wardship). */
function findWardshipGuardian(state: GameState, lord: Person, houseOrder: number): string | null {
  const year = currentYear(state);
  const manorPeople = (state.persons?.people ?? []).filter(p => p.householdId === MANOR_HOUSEHOLD);
  const houseTag = `lord-house:${houseOrder}`;
  const mother = manorPeople.find(p => p.sex === "female" && p.role === "spouse");
  if (mother !== undefined) return mother.id;
  const kin = manorPeople.find(p => p.tags.includes(houseTag) && p.id !== lord.id && ageOf(p, year) >= WARDSHIP_AGE_YEARS);
  if (kin !== undefined) return kin.id;
  return null;
}

/** FIX-11: begin wardship for a minor lord — sets guardianId in lordship state. */
export function beginWardship(state: GameState, tick: number, lord: Person): GameState {
  const lordship = lordshipOf(state);
  const guardianId = findWardshipGuardian(state, lord, lordship.house.order);
  return { ...state, lordship: { ...lordship, wardship: { guardianId, since: tick } } };
}

if (r.surgeTick === undefined) {
  const both = r.textileStreetTick !== undefined && r.alehouseBoomTick !== undefined && tick >= Math.max(r.textileStreetTick, r.alehouseBoomTick) + SEASON;
  if ((both && year >= B.surgeFromYear) || tick >= seasonOf(state, B.surgeLatestYear)) next = withReorganisation(next, r = { ...r, surgeTick: tick });

export function marriageGrooms(state: GameState): readonly GroomCandidate[] {
  const order = lordshipOf(state).house.order;
  const year = currentYear(state);
  const people = state.persons?.people ?? [];
  const married = new Set(people.flatMap(person => person.tags.filter(tag => tag.startsWith("spouse-of:")).map(tag => tag.slice("spouse-of:".length))));
  const ofAge = (person: Person) => ageOf(person, year) >= GROOM_MIN_AGE && ageOf(person, year) <= GROOM_MAX_AGE && !married.has(person.id);
  const sons = people.filter(person => person.householdId === MANOR_HOUSEHOLD && person.tags.includes(`lord-house:${order}`) && person.sex === "male"
    && person.role === "child" && ofAge(person)).sort((a, b) => a.birthYear - b.birthYear || a.id.localeCompare(b.id));
  const lord = manorLord(people, order, year);
  const widowed = lord !== undefined && lord.sex === "male" && ofAge(lord)
    && !people.some(person => person.alive && person.householdId === MANOR_HOUSEHOLD && person.tags.includes(`lord-house:${order}`)
      && person.id !== lord.id && (person.role === "spouse" || (person.role === "head" && person.sex === "female")));
  // A kin already married into the manor (a contract made) is a manor person now, no longer off the map.
  const materialised = new Set(people.flatMap(person => person.tags.filter(tag => tag.startsWith("kin-of:")).map(tag => tag.slice("kin-of:".length))));
  const kin = lordHouseKin(state).filter(entry => !materialised.has(entry.person.id) && !entry.person.tags.includes("married") && ofAge(entry.person));
  return [...sons.map(person => ({ person, relation: "son" as const })), ...(widowed ? [{ person: lord, relation: "widowed_lord" as const }] : []), ...kin];
}

/** NG-7 API: the groom (the first of `marriageGrooms`, or the one asked for) and the bride — the old lord's elder unmarried daughter. */
export function marriageCandidates(state: GameState, groomId?: string): { readonly groom: Person | null; readonly bride: Person | null; readonly relation: GroomRelation | null } {
  const grooms = marriageGrooms(state);
  const chosen = groomId === undefined ? grooms[0] : grooms.find(entry => entry.person.id === groomId);
  const estate = estatesOf(state).estates.find(entry => entry.id === MARRIAGE_ESTATE_ID);
  const bride = estatesOf(state).people.filter(person => person.alive && person.sex === "female" && person.fatherId === estate?.house?.lordId
    && !person.tags.includes("married-out")).sort((a, b) => a.birthYear - b.birthYear || a.id.localeCompare(b.id))[0] ?? null;
  return { groom: chosen?.person ?? null, bride, relation: chosen?.relation ?? null };
}

export function proposeMarriage(state: GameState, offered: readonly Term[], groomId?: string): GameState {
  if (marriageRefusal(state, offered, groomId) !== null) return state;
  const { groom, bride } = marriageCandidates(state, groomId);
  const terms = withConsent(offered);
  const diplomacy = diplomacyOf(state);
  const ordinal = diplomacy.nextNegotiation;
  const acceptance = evaluateOffer(state, LORD, COUNTERPART, terms);
  const accepted = offerDraw(state, ordinal) < acceptance.permille;
  const counter = accepted ? null : counterOffer(state, LORD, COUNTERPART, terms, `negotiation-${ordinal}`);
  const negotiation: Negotiation = { id: `negotiation-${ordinal}`, proposer: LORD, counterpart: COUNTERPART, purpose: "marriage",
    groomId: groom!.id, brideId: bride!.id, terms, acceptance, status: accepted ? "accepted" : counter === null ? "rejected" : "countered",
    ...(counter === null ? {} : { counter }), tick: state.tick, deadline: state.tick + COUNTER_ANSWER_TICKS };
  const next = withDiplomacy(state, { ...diplomacy, negotiations: [...diplomacy.negotiations, negotiation], nextNegotiation: ordinal + 1 });
  return accepted ? contract(next, negotiation, terms) : next;
}

/** NG-5: the lord takes the counter (the counterpart's own terms: it holds to them) or lets it go. */
export function answerCounter(state: GameState, negotiationId: string, accept: boolean): GameState {
  const diplomacy = diplomacyOf(state);
  const negotiation = diplomacy.negotiations.find(entry => entry.id === negotiationId);
  if (negotiation === undefined || negotiation.status !== "countered" || negotiation.counter === undefined || state.tick > negotiation.deadline) return state;
  if (accept && cashOf(negotiation.counter.terms) > Math.max(0, treasuryBalance(state))) return state;
  const settled = { ...negotiation, status: accept ? "accepted" as const : "withdrawn" as const };
  const next = withDiplomacy(state, { ...diplomacy, negotiations: diplomacy.negotiations.map(entry => entry.id === negotiationId ? settled : entry) });
  return accept ? contract(next, settled, negotiation.counter.terms) : next;
}

/** NG-5: a counter not answered within its season lapses (withdrawn). */
function lapseCounters(state: GameState): GameState {
  const diplomacy = state.diplomacy;
  if (diplomacy === undefined || !diplomacy.negotiations.some(entry => entry.status === "countered" && state.tick > entry.deadline)) return state;
  return withDiplomacy(state, { ...diplomacy, negotiations: diplomacy.negotiations.map(entry =>
    entry.status === "countered" && state.tick > entry.deadline ? { ...entry, status: "withdrawn" as const } : entry) });
}

function contract(state: GameState, negotiation: Negotiation, terms: readonly Term[]): GameState {
  let next = state;
  const cash = cashOf(terms);
  if (cash > 0) {
    const posted = postLedgerEntries(next, [{ account: "cash", category: "marriage_portion", amount: -cash,
      sourceRefs: [{ type: "claim", id: negotiation.id, detail: "marriage" }, { type: "actor", id: negotiation.counterpart }] }]);
    next = { ...next, ledger: posted.ledger, treasuryCoin: posted.treasuryCoin };
  }
  const claimed = raiseClaim(next, { claimant: LORD, estateId: MARRIAGE_ESTATE_ID, basis: "marriage" });
  const claimId = estatesOf(claimed).claims.at(-1)!.id;
  let diplomacy = contractPromises(diplomacyOf(claimed), negotiation, terms, state.tick);
  diplomacy = { ...diplomacy, relations: { ...diplomacy.relations, [negotiation.counterpart]: (diplomacy.relations[negotiation.counterpart] ?? 0) + CONTRACT_RELATION_GAIN } };
  const groomed = groomToManor(claimed, negotiation.groomId);
  // FIX-13 (NG-5b): what is not cash waits — the jointure for the groom's death, the deferred debt for the inheritance.
  const jointure = terms.find(term => term.kind === "jointure" && term.giver === "proposer")?.pieceId;
  const deferred = terms.filter(term => term.kind === "debt_after_inheritance" && term.giver === "proposer").reduce((sum, term) => sum + (term.amount ?? 0), 0);
  const plan: MarriagePlan = { negotiationId: negotiation.id, groomId: groomed.groomId, brideId: negotiation.brideId, estateId: MARRIAGE_ESTATE_ID,
    contractedTick: state.tick, stage: "contracted", claimId, events: {}, ...(jointure === undefined ? {} : { jointurePieceId: jointure }),
    ...(deferred > 0 ? { deferredDebt: deferred } : {}) };
  return withDiplomacy(groomed.state, { ...diplomacy, marriage: plan });
}

/**
 * FIX-12 (item 2, NG-7a): a groom from off the map comes to the manor at the contract — a manor person of the lord's
 * house (the family's own ordinal), tagged with the kin id he had (`kin-of:`), so he is no longer offered.
 */
function groomToManor(state: GameState, groomId: string): { readonly state: GameState; readonly groomId: string } {
  const persons = state.persons;
  if (!groomId.startsWith(KIN_PREFIX) || persons === undefined) return { state, groomId };
  const kin = lordHouseKin(state).find(entry => entry.person.id === groomId);
  if (kin === undefined) return { state, groomId };
  const ordinal = persons.lordOrdinal ?? 1;
  const id = `m-${String(ordinal).padStart(6, "0")}`;
  const order = lordshipOf(state).house.order;
  const { fatherId: _offMapFather, ...person } = kin.person;
  const groom: Person = { ...person, id, householdId: MANOR_HOUSEHOLD, role: "kin",
    tags: ["lord-family", `lord-house:${order}`, `lord-kin:${kin.relation}`, `kin-of:${groomId}`] };
  return { state: { ...state, persons: { ...persons, people: [...persons.people, groom].sort((a, b) => a.id.localeCompare(b.id)), lordOrdinal: ordinal + 1 } }, groomId: id };
}

function brideArrives(state: GameState, plan: MarriagePlan): GameState {
  const people = estatesOf(state).people;
  const bride = people.find(person => person.id === plan.brideId);
  if (bride === undefined || state.persons === undefined) return state;
  const order = lordshipOf(state).house.order;
  const moved: Person = { ...bride, householdId: MANOR_HOUSEHOLD, role: "kin", tags: ["lord-family", `lord-house:${order}`, `spouse-of:${plan.groomId}`, `born:${MARRIAGE_ESTATE_ID}`] };
  const next = withEstatePeople(state, people.map(person => person.id === bride.id ? { ...person, tags: [...person.tags, "married-out"] } : person));
  return { ...next, persons: { ...state.persons, people: [...state.persons.people, moved].sort((a, b) => a.id.localeCompare(b.id)) } };
}

/** NG-8: the couple's first child, born in the manor (the lord's family's own ordinal). */
function firstChild(state: GameState, plan: MarriagePlan): GameState {
  const persons = state.persons;
  if (persons === undefined) return state;
  const groom = persons.people.find(person => person.id === plan.groomId);
  const ordinal = persons.lordOrdinal ?? 1;
  const id = `m-${String(ordinal).padStart(6, "0")}`;
  const sex = hashSeed(state.seed, "marriage-child", ordinal) % 2 === 0 ? "male" as const : "female" as const;
  const traits = populationTraits(state.seed, "lord-child", ordinal);
  const order = lordshipOf(state).house.order;
  const draft = { id, sex, classBand: "gentry" as const, build: traits.buildBias, occupation: "", tags: ["lord-family", `lord-house:${order}`], role: "child" as const, traits };
  const child: Person = { ...draft, givenName: weightedName(sex === "male" ? MALE_GIVEN_NAMES : FEMALE_GIVEN_NAMES, hashSeed(state.seed, "lord-child", ordinal)),
    ...(groom?.surname === undefined ? {} : { surname: groom.surname }), birthYear: currentYear(state), householdId: MANOR_HOUSEHOLD, hair: hairWords(traits),
    alive: true, lineageId: groom?.lineageId ?? `lin:${id}`, motherId: plan.brideId, fatherId: plan.groomId,
    portraitIdentity: choosePortraitIdentity(state.seed, draft, ageBandOf(0), new Map()) };
  return { ...state, persons: { ...persons, people: [...persons.people, child].sort((a, b) => a.id.localeCompare(b.id)), lordOrdinal: ordinal + 1 } };
}

function inheritance(state: GameState, plan: MarriagePlan): GameState {
  const lord = oldLord(state);
  let next = lord === undefined ? state : withEstatePeople(state, estatesOf(state).people.map(person => person.id === lord.id ? { ...person, alive: false, deathYear: currentYear(state), deathCause: "age" as const } : person));
  const son = plan.brotherInLawId === undefined ? undefined : estatesOf(next).people.find(person => person.id === plan.brotherInLawId && person.alive);
  const events = { ...plan.events, father_died: state.tick };
  if (son !== undefined) {
    next = claimStatus(estateTo(next, MARRIAGE_ESTATE_ID, `person:${son.id}`), plan.claimId, "lapsed");
    return withPlan(next, { ...plan, stage: "lost", events });
  }
  if (plan.rival !== undefined) return withPlan(estateTo(next, MARRIAGE_ESTATE_ID, plan.rival), { ...plan, stage: "contested", events });
  next = claimStatus(estateTo(next, MARRIAGE_ESTATE_ID, LORD), plan.claimId, "won");
  return withPlan(deferredDebtDue(next, plan), { ...plan, stage: "inherited", events });
}

/**
 * WR-2…WR-8: the lord's answer to a war petition (called by `respondToPetition`, which records the decision and marks
 * the petition answered). `expired` is a demand left unanswered: it counts as a refusal.
 */
export function answerWarPetition(state: GameState, petition: PetitionRecord, response: PetitionResponse | "expired"): GameState {
  const war = warOf(state);
  if (war === undefined) return state;
  const refused = response === "refuse" || response === "expired";
  const source: readonly [SourceRef, ...SourceRef[]] = [CROWN, { type: "claim", id: petition.id, detail: petition.defId }];
  let next: GameState = withWar(state, { ...war, answers: { ...war.answers, [petition.defId]: response },
    ...(refused && petition.petitioner === "crown" ? { favour: false } : {}) });

/** SW-2: the estates the lord came to hold get their oversight (direct, the most loyal candidate keeping the accounts). */
function ensureOversight(state: GameState): GameState {
  const held = heldOffMapEstates(state);
  const current = stewardshipOf(state);
  const missing = held.filter(estate => !current.oversight.some(entry => entry.estateId === estate.id));
  if (missing.length === 0) return state;
  let next = state;
  let stewardship = current;
  for (const estate of missing) {
    const made = makeCandidates(next, estate.id);
    const receiver = [...made.stewards].sort((a, b) => b.loyalty - a.loyalty || a.personId.localeCompare(b.personId))[0]!;
    next = { ...next, estates: { ...estatesOf(next), people: [...estatesOf(next).people, ...made.people] } };
    stewardship = { ...stewardship, stewards: [...stewardship.stewards, ...made.stewards.map(record => record === receiver ? { ...record, status: "serving" as const } : record)],
      oversight: [...stewardship.oversight, { estateId: estate.id, mode: "direct", stewardId: receiver.personId, auditMode: "accounts", tenants: 0, merchants: 0,
      undetected: 0, since: state.tick }] };
  }
  return withStewardship(next, stewardship);
}

